[
  {
    "hypothesis_id": 23,
    "feature": {
      "name": "any_comment_specific_verifiable_procedural_example",
      "dtype": "binary",
      "source_columns": [
        "OC_comments"
      ],
      "definition": "Counter-argument comments (OC_comments): any comment employs a specific, verifiable procedural example (concrete named/described process, rule, procedure or case of how something is actually done that could be checked)",
      "kind": "prompt",
      "spec": "Read the OC_comments JSON list for the row (comments by users other than the OP). Return 1 if at least one comment itself employs a specific, verifiable procedural example: a concrete, particular instance or description of an actual procedure, process, rule, protocol or practice (e.g. how a legal, administrative, scientific or institutional process actually works or worked in a specific case) that could in principle be checked, as support for its rebuttal. Illustrative examples are nonexhaustive. Do not require outside verification; judge only from the supplied text. Vague generalities, hypotheticals and purely abstract/theoretical reasoning do not count. Ignore quoted OP text. Return 0 if the list is valid and no comment does so (including valid empty list). Return null if OC_comments is missing or malformed. Do not use any other columns.  "
    }
  },
  {
    "hypothesis_id": 50,
    "feature": {
      "name": "any_comment_names_specific_program_or_location",
      "dtype": "binary",
      "source_columns": [
        "OC_comments"
      ],
      "definition": "Counter-argument comments (OC_comments): any comment references a specific, named external program or location as part of its argument",
      "kind": "prompt",
      "spec": "Read the OC_comments JSON list (comments by users other than the OP). Return 1 if at least one comment references a specific, named external program (e.g., a named government/social/educational/software program, initiative or policy program) or a specific, named location (e.g., a named country, city, region, institution site or place) in making its argument. Generic unnamed categories (e.g., 'some programs', 'a country') do not count; illustrative examples here are nonexhaustive. Endorsement is not required, and the reference may be in quoted text only if it is the commenter's own use; ignore bot/moderator notices. Return 0 if the list is valid and no comment has such a named reference (including empty list). Return null if OC_comments is missing or malformed. Do not use other columns."
    }
  }
]

